 Disclosure advanced=new Disclosure(a,p,"Rule timing & GPS states","Boundary delay, edge buffer and driving thresholds");dwell=input(advanced.body,"Boundary delay · seconds","2.5",true);margin=input(advanced.body,"Boundary buffer · meters","5",true);stop=input(advanced.body,"Stopped at or below · mph","1",true);drive=input(advanced.body,"Driving at or above · mph","3",true);for(EditText e:new EditText[]{dwell,margin,stop,drive})watch(e,()->{settingsDirty=true;advanced.summary("Unsaved changes");});a.addButton(advanced.body,button("Save rule settings",()->{try{int delay=(int)Math.round(numeric(dwell,0,10)*1000),edge=(int)Math.round(numeric(margin,0,50));double st=numeric(stop,0,20),dr=numeric(drive,.1,30);if(dr<=st)throw new Exception("Driving threshold must exceed stopped threshold.");write(Arrays.asList("SET_GEO_SETTINGS|"+delay+"|"+edge+"|"+String.format(Locale.US,"%.2f|%.2f",st,dr)),()->{settingsDirty=false;advanced.summary("Saved on controller");},null);}catch(Exception e){a.notice(e.getMessage());}}));
