 private void requestSettings(){areasReady=false;reading=true;readConfig=readList=false;readAt=SystemClock.elapsedRealtime();if(feedback!=null)feedback.setText("Reading location settings from controller…");a.send("GET_GEO_CONFIG");a.send("GET_GEO_AREAS");}
 private void reloadRules(boolean user){if(!a.isConnected()){a.notice("Connect the Heltec to refresh settings.");return;}if(awaiting!=null){a.notice("Wait for the current save.");return;}readAttempts++;if(m.capabilities.contains("GEO_RULES"))requestSettings();else{reading=true;readConfig=readList=false;readAt=SystemClock.elapsedRealtime();if(feedback!=null)feedback.setText("Checking controller support…");a.send("GET_CAPS");}if(user)a.notice("Refreshing location settings…");update();}
 private boolean write(List<String> commands,Runnable done,Runnable failed){if(!available()){a.notice("Connect firmware 0.7.0 and read location settings first.");return false;}if(awaiting!=null){a.notice("Wait for the current save.");return false;}queue.clear();queue.addAll(commands);requestedControl=commands.get(0).startsWith("GEO_CONTROL|")?commands.get(0).substring(12):null;success=done;failure=failed;if(feedback!=null)feedback.setText("Saving… waiting for controller confirmation");next();return true;}
 private void next(){if(queue.isEmpty()){awaiting=null;requestedControl=null;if(feedback!=null)feedback.setText("Saved on controller");a.notice("Saved on controller");Runnable done=success;success=failure=null;if(editorSave!=null)editorSave.setEnabled(true);if(editor!=null){editor.setCancelable(true);if(editor.getButton(-2)!=null)editor.getButton(-2).setEnabled(true);}if(done!=null)done.run();update();return;}String command=queue.removeFirst();awaiting=command.split("\\|",2)[0];sent=SystemClock.elapsedRealtime();a.send(command);update();}
 private void failed(String message){queue.clear();awaiting=null;requestedControl=null;if(feedback!=null)feedback.setText(message);if(editorSave!=null)editorSave.setEnabled(true);if(editor!=null){editor.setCancelable(true);if(editor.getButton(-2)!=null)editor.getButton(-2).setEnabled(true);}Runnable done=failure;success=failure=null;if(done!=null)done.run();a.notice(message);update();}
 void record(String line){String[] x=line.split("\\|",-1);if(x[0].equals("GPS"))gpsAt=SystemClock.elapsedRealtime();boolean changed=geo.apply(line,SystemClock.elapsedRealtime());if(x[0].equals("CAPS")){if(m.capabilities.contains("GEO_RULES"))requestSettings();else{reading=false;if(feedback!=null)feedback.setText("Location rules need firmware 0.7.0 or newer. Refresh after updating the controller.");}}if(x[0].equals("GEO_LIST_END")&&changed)areasReady=true;if(reading){if(x[0].equals("GEO_CONFIG")&&changed)readConfig=true;if(x[0].equals("GEO_LIST_END")&&changed)readList=true;if(readConfig&&readList){reading=false;if(feedback!=null)feedback.setText("Location settings refreshed from controller");}}if(awaiting!=null&&x.length>1&&x[0].equals("OK")&&x[1].equals(awaiting))next();else if(awaiting!=null&&x[0].equals("ERR"))failed("Save rejected: "+(x.length>1?x[1].replace('_',' '):"unknown error"));if(x[0].equals("WARN"))a.notice("Manual override is active but could not be saved across restart.");if(changed)refresh();update();}
 private void refresh(){if(revision==geo.revision)return;revision=geo.revision;setting=true;if(spacing!=null&&!groundDirty){spacing.setText(String.format(Locale.US,"%.3f",geo.spacing*.001));width.setText(String.format(Locale.US,"%.3f",geo.width*.001));offset1.setText(String.format(Locale.US,"%.3f",geo.offset[0]*.001));offset2.setText(String.format(Locale.US,"%.3f",geo.offset[1]*.001));reverse1.setChecked(geo.reverse[0]);reverse2.setChecked(geo.reverse[1]);}if(dwell!=null&&!settingsDirty){dwell.setText(String.format(Locale.US,"%.1f",geo.dwell*.001));margin.setText(Integer.toString(geo.margin));stop.setText(String.format(Locale.US,"%.1f",geo.stopped));drive.setText(String.format(Locale.US,"%.1f",geo.driving));}setting=false;for(int i=0;i<3;i++)if(fallback[i]!=null){fallback[i].from(geo.fallback[i]);if(!fallback[i].dirty)fallbackSections[i].summary(actionLabel(geo.fallback[i]));}renderAreas();}
 private void renderAreas(){if(areaList==null)return;controls.removeAll(areaButtons);areaButtons.clear();int controlsStart=controls.size();areaList.removeAllViews();if(geo.areas.isEmpty())areaList.addView(a.text("No saved areas. Add a property, scale or delivery location.",13,0xffa2b1c4));for(GeoModel.Area area:geo.areas){a.gap(areaList,12);areaList.addView(a.text(area.name+(area.enabled?"":" · disabled"),16,0xffedf3fa));areaList.addView(a.text((area.shape.equals("C")?"Circle · "+area.radius+" m":"Boundary · "+area.points.size()+" corners")+" · priority "+area.priority+"\nDriving: "+actionLabel(area.actions[0])+" · Stopped: "+actionLabel(area.actions[1]),12,0xffa2b1c4));a.pair(areaList,button("Edit",()->editArea(area)),button(area.enabled?"Disable":"Enable",()->{GeoModel.Area copy=area.copy();copy.enabled=!copy.enabled;upload(copy,null);}));a.addButton(areaList,button("Remove area",()->new AlertDialog.Builder(a).setTitle("Remove "+area.name+"?").setMessage("This deletes the saved lighting area from the controller.").setNegativeButton("Keep",null).setPositiveButton("Remove",(d,w)->write(Arrays.asList("GEO_DELETE|"+area.id),null,null)).show()));}areaButtons.addAll(controls.subList(controlsStart,controls.size()));}
 private void enableTree(View v,boolean enabled){v.setEnabled(enabled);if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++)enableTree(((android.view.ViewGroup)v).getChildAt(i),enabled);}
 void update(){boolean editing=awaiting==null;if(editorContent!=null)enableTree(editorContent,editing);for(ActionForm form:fallback)if(form!=null)enableTree(form.root,editing);for(EditText e:new EditText[]{spacing,width,offset1,offset2,dwell,margin,stop,drive})if(e!=null)e.setEnabled(editing);if(reverse1!=null){reverse1.setEnabled(editing);reverse2.setEnabled(editing);}boolean available=available()&&awaiting==null;for(Button b:controls){b.setEnabled(available);b.setAlpha(available?1f:.4f);}if(refreshButton!=null){refreshButton.setEnabled(a.isConnected()&&awaiting==null);refreshButton.setAlpha(refreshButton.isEnabled()?1f:.4f);}if(autoButton!=null){a.selected(autoButton,geo.ready&&geo.enabled&&!geo.manualOverride);a.selected(pauseButton,geo.ready&&geo.enabled&&geo.manualOverride);a.selected(offButton,geo.ready&&!geo.enabled);autoButton.setText("AUTO".equals(requestedControl)?"Enabling… waiting for controller":"Enable / resume auto");pauseButton.setText("PAUSE".equals(requestedControl)?"Pausing… waiting for controller":"Pause for manual");offButton.setText("OFF".equals(requestedControl)?"Turning off… waiting for controller":"Turn location rules off");}if(status!=null){String control=!a.isConnected()?"Not connected":(!geo.ready||!areasReady)?(!m.capabilities.contains("GEO_RULES")&&m.capsReceived?"Controller firmware does not report location rules · update to 0.7.0+":reading?"Reading location rules… controls unlock after controller reply":"Location settings not received · tap Refresh"):!geo.enabled?"Location automation is off":geo.manualOverride?"Paused · manual control":SystemClock.elapsedRealtime()-geo.stateAt>5000?"Auto enabled · waiting for controller state":"Auto · "+geo.source+"\n"+geo.motion.replace('_',' ')+" · "+(geo.active?actionLabel(geo.activeAction):"Normal lighting")+(geo.pending?" · boundary transition pending":"");status.setText(control);}if(groundStatus!=null)groundStatus.setText(a.isConnected()&&geo.groundFresh&&SystemClock.elapsedRealtime()-geo.groundAt<4000?String.format(Locale.US,"GPS speed · %.1f mph",geo.speed):"No fresh GPS speed · motion paused");}
 void tick(){long now=SystemClock.elapsedRealtime();if(reading&&now-readAt>6000){reading=false;if(feedback!=null)feedback.setText("Location settings reply incomplete. Tap Refresh to retry; unsaved edits are retained.");}if(a.isConnected()&&(!geo.ready||!areasReady)&&awaiting==null&&!reading&&readAttempts<3&&now-readAt>6000)reloadRules(false);if(awaiting!=null&&SystemClock.elapsedRealtime()-sent>7000)failed("Save confirmation timed out. Refresh controller settings before retrying.");update();}
