 private void upload(GeoModel.Area area,Runnable done){if(area.points.size()<(area.shape.equals("C")?1:3)||area.points.size()>12){a.notice("A circle needs a center; a boundary needs 3–12 corners.");return;}List<String> commands=new ArrayList<>();commands.add("GEO_BEGIN|"+area.id+"|"+area.name+"|"+area.priority+"|"+(area.enabled?1:0)+"|"+area.shape+"|"+area.radius);for(GeoModel.Point point:area.points)commands.add(String.format(Locale.US,"GEO_POINT|%.7f|%.7f",point.lat,point.lon));for(int i=0;i<2;i++)commands.add("GEO_ACTION|"+GeoModel.STATES[i]+"|"+area.actions[i].wire());commands.add("GEO_COMMIT");if(write(commands,done,null)&&editor!=null&&editor.isShowing()){editor.setCancelable(false);editorSave.setEnabled(false);editor.getButton(-2).setEnabled(false);}}
